  function inject() {
    if (document.getElementById('mv-icons')) return;
    var parts = [];
    Object.keys(S).forEach(function (id) {
      parts.push('<symbol id="' + id + '" viewBox="' + (VIEWBOX[id] || '0 0 24 24') + '">' + S[id] + '</symbol>');
    });
    Object.keys(ART).forEach(function (id) {
      parts.push('<symbol id="' + id + '" viewBox="' + ART[id].viewBox + '">' + ART[id].body + '</symbol>');
    });
    var host = document.createElement('div');
    host.innerHTML = '<svg id="mv-icons" width="0" height="0" style="position:absolute" aria-hidden="true"><defs>' + ART_DEFS + '</defs>' + parts.join('') + '</svg>';
    document.body.insertBefore(host.firstChild, document.body.firstChild);
  }

